def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'C'

    my_defects = 0
    opp_defects = 0
    punish_count = 0
    forgive_count = 0
    aggression_count = 0
    has_consecutive_D = False
    last_defect_round = -1

    for i in range(n):
        me, opp = history[i]
        if me == 'D':
            my_defects += 1
            last_defect_round = i
        if opp == 'D':
            opp_defects += 1
        if i > 0:
            prev_me, prev_opp = history[i-1]
            if prev_me == 'D':
                if opp == 'C':
                    forgive_count += 1
                else:
                    punish_count += 1
            else:
                if opp == 'D':
                    aggression_count += 1
            if me == 'D' and prev_me == 'D':
                has_consecutive_D = True

    last_me, last_opp = history[-1]

    total_my_C = n - my_defects
    if total_my_C > 0 and n >= 10:
        if aggression_count / total_my_C > 0.5:
            return 'D'

    if opp_defects == n:
        return 'D'

    if opp_defects == 0:
        if my_defects == 0:
            return 'D'
        if not has_consecutive_D and n > 25:
            return 'D'
        if has_consecutive_D:
            return 'D'
        if last_me == 'D':
            return 'C'
        else:
            return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
        else:
            return 'C'

    if last_me == 'D':
        return 'C'

    if punish_count == 0 and forgive_count > 0:
        interval = 2
    elif forgive_count > punish_count:
        interval = 4
    elif punish_count > forgive_count:
        interval = 10
    else:
        interval = 6

    if last_defect_round == -1:
        if n >= 10:
            return 'D'
        else:
            return 'C'
    else:
        if n - last_defect_round >= interval:
            return 'D'
        else:
            return 'C'
